package com.gregtech.gregtech.worldgen.center;

import java.nio.file.*;
import java.util.*;

/** Compares actual before/after planners with a bounded recording delegate, not a game world. */
public final class CenterProbe {
    private static final class Recorder implements OriginWorld {
        final int minX,minZ;
        long fingerprint=0xcbf29ce484222325L, writes;
        int lowest=Integer.MAX_VALUE, highest=Integer.MIN_VALUE, litter;
        String biome,spawn;
        final List<String> trees=new ArrayList<>();
        Recorder(int x,int z){minX=x;minZ=z;}
        void value(long value){fingerprint=(fingerprint^value)*0x100000001b3L;}
        public int minY(){return -64;}
        public int maxY(){return 320;}
        public boolean canWrite(int x,int y,int z){return x>=minX&&x<minX+16&&z>=minZ&&z<minZ+16&&y>=-64&&y<320;}
        public Block getBlock(int x,int y,int z){return OriginSupport.NB;}
        public boolean setBlock(int x,int y,int z,Block block,int metadata,int flags){
            if(!canWrite(x,y,z))return false;
            value(1);value(x);value(y);value(z);value(block.id().hashCode());value(metadata);value(flags);value(block.slabSide());
            writes++;lowest=Math.min(lowest,y);highest=Math.max(highest,y);return true;
        }
        public Biome getBiomeGenForCoords(int x,int z){return new Biome("plains","Plains");}
        public boolean isInfiniteWaterBiome(String name){return false;}
        public void setSpawnLocation(int x,int y,int z){spawn=x+","+y+","+z;value(2);value(x);value(y);value(z);}
        public void biome(Chunk chunk,String name){biome=name;value(3);value(name.hashCode());}
        public void tree(int x,int y,int z,int wood,int height,Random random){
            trees.add(x+","+y+","+z+","+wood+","+height);value(4);value(x);value(y);value(z);value(wood);value(height);
        }
        public void litter(int x,int y,int z,int legacy,boolean flint){
            litter++;value(5);value(x);value(y);value(z);value(legacy);value(flint?1:0);
        }
        public void sign(int x,int y,int z,int side,int flags,String... lines){throw new AssertionError("Unexpected sign");}
        public void beacon(int x,int y,int z,String primary,String secondary){throw new AssertionError("Unexpected beacon");}
        public void clearNonPlayerEntities(int x,int y,int z,int xx,int yy,int zz){throw new AssertionError("Unexpected entities");}
    }
    public static void main(String[] args)throws Exception{
        var before=new BeforeSourceCenterBiomes(66);
        var after=new SourceCenterBiomes(66);
        int chunks=0,trees=0,litter=0;
        long writes=0;
        var biomes=new TreeMap<String,Integer>();
        for(int x=-96;x<=80;x+=16)for(int z=-96;z<=80;z+=16){
            Recorder a=new Recorder(x,z),b=new Recorder(x,z);
            long seed=((long)(x>>4)&0xffffffffL)|(((long)(z>>4)&0xffffffffL)<<32);
            boolean oldResult=before.generate(a,new OriginWorld.Chunk(a,x,z),x,z,new Random(seed));
            boolean newResult=after.generate(b,new OriginWorld.Chunk(b,x,z),x,z,new Random(seed));
            if(oldResult!=newResult||a.fingerprint!=b.fingerprint||a.writes!=b.writes||a.lowest!=b.lowest||a.highest!=b.highest
                ||a.litter!=b.litter||!a.trees.equals(b.trees)||!Objects.equals(a.biome,b.biome)||!Objects.equals(a.spawn,b.spawn))
                throw new AssertionError("Before/after requests differ at "+x+","+z);
            if(!newResult)throw new AssertionError("Centre chunk declined");
            chunks++;writes+=b.writes;trees+=b.trees.size();litter+=b.litter;biomes.merge(b.biome,1,Integer::sum);
        }
        var outside=new Recorder(96,96);
        if(after.generate(outside,new OriginWorld.Chunk(outside,96,96),96,96,new Random(0))||outside.writes!=0)
            throw new AssertionError("Outside centre accepted");
        int names=0;
        for(String name:Files.readAllLines(Path.of(args[0]))){
            if(!OriginBiomeNames.water(name)||!OriginBiomeNames.water(name.toUpperCase(Locale.ROOT))
                ||!OriginBiomeNames.water(String.join("_",name.split(""))))throw new AssertionError("Water alias lost: "+name);
            names++;
        }
        if(OriginBiomeNames.water("river_valley"))throw new AssertionError("Unlisted name guessed");
        System.out.println("CHUNKS "+chunks);
        System.out.println("WRITES "+writes);
        System.out.println("TREE_REQUESTS "+trees);
        System.out.println("LITTER_REQUESTS "+litter);
        System.out.println("BIOMES "+biomes);
        System.out.println("WATER_NAMES "+names);
        System.out.println("OUTSIDE_REJECTED true");
    }
}

